INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Pipelining immer auf CPUs beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in Netzwerken oder Software genutzt"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel von Pipelining?', 3, '[{"text": "Effizienzsteigerung", "correct": true, "because": "Parallele Verarbeitung von Schritten"}, {"text": "Datenkompression", "correct": false, "because": "Andere Technik"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche nutzen Pipelining?', 5, '[{"text": "CPU-Befehlsverarbeitung", "correct": true, "because": "Teilt Befehle in Schritte"}, {"text": "Datenübertragung", "correct": true, "because": "Segmentiert Datenströme"}, {"text": "Bildbearbeitung", "correct": false, "because": "Weniger typisch"}, {"text": "Musikwiedergabe", "correct": false, "because": "Andere Domäne"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Pipelining erhöht Durchsatz. b) Es eliminiert Latenz komplett.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) reduziert, aber nicht eliminiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Implementierung von Pipelining?', 4, '[{"text": "Abhängigkeiten", "correct": false, "because": "Können Konflikte verursachen"}, {"text": "Pipeline-Stufen", "correct": false, "because": "Bestimmen Ablauf"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Pipelining immer mehrere Prozessoren benötigt?', 2, '[{"text": "Nein", "correct": true, "because": "Ein Prozessor kann pipelinen"}, {"text": "Ja", "correct": false, "because": "Einzelne CPU ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Konzept ist für Pipelining entscheidend?', 3, '[{"text": "Schrittweise Verarbeitung", "correct": true, "because": "Teilt Aufgaben in Phasen"}, {"text": "Einzelverarbeitung", "correct": false, "because": "Sequentielle Methode"}, {"text": "Manuelle Zuweisung", "correct": false, "because": "Automatisierung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei Pipelining?', 5, '[{"text": "Pipeline-Konflikte", "correct": true, "because": "Abhängigkeiten stören Ablauf"}, {"text": "Ressourcenengpässe", "correct": true, "because": "Begrenzen Effizienz"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Nicht primär relevant"}, {"text": "Einfache Schleifen", "correct": false, "because": "Keine Herausforderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Pipelining verbessert Leistung. b) Es ist immer konfliktfrei. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hat Konfliktpotenzial"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Pipelining?', 4, '[{"text": "Stufenaufteilung", "correct": false, "because": "Kern des Pipelining"}, {"text": "Konfliktmanagement", "correct": false, "because": "Vermeidet Stalls"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Kein Pipelining-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Pipelining nur für Hardware relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in Software wie CI/CD"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendungen profitieren von Pipelining?', 4, '[{"text": "Prozessorbefehle", "correct": true, "because": "Parallele Ausführung"}, {"text": "Datenströme", "correct": true, "because": "Segmentierte Übertragung"}, {"text": "Statische Daten", "correct": false, "because": "Weniger geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Pipelining immer Latenz reduziert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Durchsatz steigt, Latenz bleibt"}, {"text": "Ja", "correct": false, "because": "Latenz nicht primär reduziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Implementierung von Pipelining?', 3, '[{"text": "Konfliktvermeidung", "correct": true, "because": "Sichert reibungslosen Ablauf"}, {"text": "Maximale Komplexität", "correct": false, "because": "Erschwert Design"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Pipelining teilt Aufgaben in Stufen. b) Es funktioniert nur mit GPUs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht exklusiv"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Mechanismen unterstützen Pipelining?', 5, '[{"text": "Befehlsvorhersage", "correct": true, "because": "Reduziert Stalls in CPUs"}, {"text": "Pufferung", "correct": true, "because": "Zwischenspeichert Daten"}, {"text": "Statische Daten", "correct": false, "because": "Keine Unterstützung"}, {"text": "Manuelle Eingaben", "correct": false, "because": "Nicht automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Pipelining unwichtig?', 3, '[{"text": "Stufenoptimierung", "correct": false, "because": "Steigert Effizienz"}, {"text": "Ressourcenplanung", "correct": false, "because": "Vermeidet Engpässe"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Pipelining-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Pipelining für Echtzeitanwendungen geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Steigert Durchsatz"}, {"text": "Nein", "correct": false, "because": "Echtzeit möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verursacht Pipelining immer Overhead?', 3, '[{"text": "Ja", "correct": true, "because": "Koordination kostet Ressourcen"}, {"text": "Nein", "correct": false, "because": "Overhead oft vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu Pipelining?', 4, '[{"text": "Befehlsverarbeitung in CPUs", "correct": true, "because": "Parallele Schritte"}, {"text": "Manuelle Dateneingabe", "correct": false, "because": "Keine Parallelität"}, {"text": "Einfache Textausgabe", "correct": false, "because": "Sequentielle Aufgabe"}]');
